{
  "findings": [
    {
      "check_id": "CKV_GCP_29",
      "title": "Publicly accessible firewall rule for HTTP/HTTPS",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows ingress from any source (0.0.0.0/0) on ports 80 and 443. While common for public web servers, this exposes the instance to the entire internet, increasing the attack surface for DDoS, brute-force, or vulnerability exploitation if the underlying application is not properly hardened."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "No code changes were applied because allowing public access on ports 80 and 443 is a standard architectural requirement for public-facing web services. Restricting these ports would break functionality unless specific client IP ranges are known, which are not provided in the context. The finding is reported as informational/Medium risk due to inherent exposure."
}
